(function(global){
  class Chart {
    constructor(canvas,config){
      this.canvas=canvas&&canvas.canvas?canvas.canvas:canvas;
      this.ctx=this.canvas.getContext('2d');
      this.config=config||{};
      this.resizeHandler=()=>this.render();
      global.addEventListener('resize',this.resizeHandler);
      this.render();
    }
    destroy(){
      global.removeEventListener('resize',this.resizeHandler);
      if(this.ctx)this.ctx.clearRect(0,0,this.canvas.width,this.canvas.height);
    }
    render(){
      const c=this.canvas,ctx=this.ctx,rect=c.getBoundingClientRect();
      const w=Math.max(320,Math.floor(rect.width||c.width||600));
      const h=Math.max(180,Math.floor(rect.height||c.height||260));
      const dpr=global.devicePixelRatio||1;
      c.width=w*dpr;c.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);
      ctx.clearRect(0,0,w,h);
      ctx.font='11px Arial';ctx.fillStyle='#475569';ctx.strokeStyle='#cbd5e1';ctx.lineWidth=1;
      const type=(this.config.type||'bar').toLowerCase();
      const data=this.config.data||{},labels=data.labels||[],datasets=data.datasets||[];
      if(!labels.length||!datasets.length){ctx.fillText('No chart data available.',18,28);return;}
      if(type==='doughnut'||type==='pie')return this.drawPie(w,h,labels,datasets[0]);
      if(type==='line')return this.drawLine(w,h,labels,datasets);
      return this.drawBar(w,h,labels,datasets);
    }
    values(ds){return (ds.data||[]).map(v=>Number(v)||0)}
    palette(i){return ['#1e40af','#15803d','#d97706','#dc2626','#7c3aed','#0891b2','#475569','#be185d'][i%8]}
    axes(w,h,max){
      const left=42,right=16,top=18,bottom=42;
      this.ctx.strokeStyle='#e2e8f0';
      for(let i=0;i<=4;i++){const y=top+(h-top-bottom)*i/4;this.ctx.beginPath();this.ctx.moveTo(left,y);this.ctx.lineTo(w-right,y);this.ctx.stroke();this.ctx.fillStyle='#64748b';this.ctx.fillText(String(Math.round(max*(4-i)/4)),5,y+4)}
      return {left,right,top,bottom,pw:w-left-right,ph:h-top-bottom};
    }
    drawBar(w,h,labels,datasets){
      const all=datasets.flatMap(ds=>this.values(ds)),max=Math.max(1,...all);
      const a=this.axes(w,h,max),groups=Math.max(1,labels.length),groupW=a.pw/groups,barW=Math.max(5,groupW/(datasets.length+1));
      datasets.forEach((ds,di)=>this.values(ds).forEach((v,i)=>{
        const bh=a.ph*v/max,x=a.left+i*groupW+(di+.5)*barW,y=a.top+a.ph-bh;
        this.ctx.fillStyle=Array.isArray(ds.backgroundColor)?ds.backgroundColor[i]:(ds.backgroundColor||this.palette(di));
        this.ctx.fillRect(x,y,barW*.82,bh);
      }));
      labels.forEach((label,i)=>{this.ctx.save();this.ctx.translate(a.left+(i+.5)*groupW,h-8);this.ctx.rotate(labels.length>7?-0.45:0);this.ctx.textAlign=labels.length>7?'right':'center';this.ctx.fillStyle='#475569';this.ctx.fillText(String(label).slice(0,18),0,0);this.ctx.restore()});
    }
    drawLine(w,h,labels,datasets){
      const all=datasets.flatMap(ds=>this.values(ds)),max=Math.max(1,...all),a=this.axes(w,h,max),step=labels.length>1?a.pw/(labels.length-1):a.pw;
      datasets.forEach((ds,di)=>{
        const vals=this.values(ds);this.ctx.strokeStyle=ds.borderColor||this.palette(di);this.ctx.lineWidth=2;this.ctx.beginPath();
        vals.forEach((v,i)=>{const x=a.left+i*step,y=a.top+a.ph-a.ph*v/max;i?this.ctx.lineTo(x,y):this.ctx.moveTo(x,y)});
        this.ctx.stroke();vals.forEach((v,i)=>{const x=a.left+i*step,y=a.top+a.ph-a.ph*v/max;this.ctx.fillStyle=ds.borderColor||this.palette(di);this.ctx.beginPath();this.ctx.arc(x,y,3,0,Math.PI*2);this.ctx.fill()});
      });
      labels.forEach((label,i)=>{if(labels.length>12&&i%2)return;this.ctx.textAlign='center';this.ctx.fillStyle='#475569';this.ctx.fillText(String(label).slice(0,12),a.left+i*step,h-9)});
    }
    drawPie(w,h,labels,ds){
      const vals=this.values(ds),total=vals.reduce((a,b)=>a+b,0)||1,cx=w*.34,cy=h*.5,r=Math.min(w,h)*.3,inner=(this.config.type||'').toLowerCase()==='doughnut'?r*.55:0;let angle=-Math.PI/2;
      vals.forEach((v,i)=>{const next=angle+Math.PI*2*v/total;this.ctx.beginPath();this.ctx.arc(cx,cy,r,angle,next);if(inner)this.ctx.arc(cx,cy,inner,next,angle,true);else this.ctx.lineTo(cx,cy);this.ctx.closePath();this.ctx.fillStyle=Array.isArray(ds.backgroundColor)?ds.backgroundColor[i]:this.palette(i);this.ctx.fill();angle=next});
      labels.forEach((label,i)=>{const y=20+i*19;if(y>h-8)return;this.ctx.fillStyle=Array.isArray(ds.backgroundColor)?ds.backgroundColor[i]:this.palette(i);this.ctx.fillRect(w*.68,y-9,10,10);this.ctx.fillStyle='#475569';this.ctx.fillText(String(label).slice(0,20)+' ('+vals[i]+')',w*.68+15,y)});
    }
  }
  Chart.defaults={};
  global.Chart=Chart;
})(window);